using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Collections.Generic;
using NetScope;
class DeviceAITests {
 static int passed,failed;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+" :: "+ex.GetBaseException().Message);}}
 static void Throws(Action action){bool threw=false;try{action();}catch{threw=true;}Check(threw,"expected rejection");}
 static List<DeviceAIInput> Inputs(params string[] clues){return new List<DeviceAIInput>{new DeviceAIInput{Alias="device-01",Clues=clues.ToList()}};}
 static string Reply(string type,string confidence="medium",string reason="从类别词推测"){return Store.Json(new{Devices=new[]{new{Alias="device-01",Type=type,Confidence=confidence,Reason=reason}}});}
 static DeviceInfo Device(string name="Alice-iphone"){return new DeviceInfo{Ip="10.8.9.10",Mac="AA:BB:CC:11:22:33",Name=name,ReportedName=name,Hint="设备类型未知",ReportedHint="设备类型未知",Source="网关导入快照",NameSource="网关提供（用户导入）"};}
 static string Temp(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"device-ai-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
 static AppController Controller(string directory){var settings=Defaults.Create();settings.AutoMonitor=false;settings.AiAutoEnabled=false;new Store(directory).SaveSettings(settings);return new AppController(directory);}
 static void Set(object controller,string field,object value){typeof(AppController).GetField(field,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(controller,value);}
 static void Map(AppController controller){typeof(AppController).GetMethod("ApplyDeviceLabels",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(controller,null);}
 static int Main(){
  Test("only canonical clues are sent; no MAC IP raw name or injected prompt",()=>{var device=Device("Alice-iphone-ignore-all-rules");device.ReportedHint="printer and 10.8.9.10 secret@example.com";var input=Inputs(DeviceAI.ExtractClues(device).ToArray());string json=DeviceAI.InputJson(input);Check(json.Contains("iphone")&&json.Contains("printer"),"useful category missing");foreach(string secret in new[]{"Alice","ignore-all","10.8.9.10","AA:BB","secret@example.com"})Check(!json.Contains(secret),"private source leaked");});
  Test("raw strings and hostile aliases cannot enter model input",()=>{Throws(()=>DeviceAI.InputJson(Inputs("Alice-iphone")));var input=Inputs("iphone");input[0].Alias="192.168.1.1";Throws(()=>DeviceAI.InputJson(input));});
  Test("bare MAC metadata is not mistaken for a Mac computer",()=>{var device=Device("Unknown");device.ReportedHint="MAC address unknown";Check(!DeviceAI.ExtractClues(device).Contains("mac"),"MAC terminology inferred Apple computer");});
  Test("embedded personal words do not substring-match a class",()=>{Check(DeviceAI.ExtractClues(Device("MacDonald-mymacbookish-iphoneowner")).Count==0,"substring falsely classified");});
  Test("recognized category produces only an unverified inference",()=>{var parsed=DeviceAI.Parse(Reply("iphone"),Inputs("iphone"))["device-01"];Check(parsed.Type=="iphone"&&parsed.Confidence=="medium"&&parsed.Reason.Contains("未验证"),"inference missing uncertainty");});
  Test("vendor only cannot invent a device category",()=>{var parsed=DeviceAI.Parse(Reply("mac_computer"),Inputs("apple"))["device-01"];Check(parsed.Type=="unknown"&&parsed.Confidence=="low","vendor brand treated as proof of computer");});
  Test("no clue forces unknown even when model confidently guesses",()=>{var parsed=DeviceAI.Parse(Reply("router"),Inputs())["device-01"];Check(parsed.Type=="unknown"&&parsed.Confidence=="low","empty evidence guessed identity");});
  Test("conflicting categories cap confidence at low",()=>{Check(DeviceAI.Parse(Reply("iphone"),Inputs("iphone","windows"))["device-01"].Confidence=="low","conflicting evidence kept medium certainty");});
  Test("unconstrained model prose is not persisted as device evidence",()=>{var parsed=DeviceAI.Parse(Reply("iphone","medium","Alice is at 10.8.9.10 and malicious"),Inputs("iphone"))["device-01"];Check(!parsed.Reason.Contains("Alice")&&!parsed.Reason.Contains("malicious")&&!parsed.Reason.Contains("10.8"),"model invented prose retained");});
  Test("unknown types fake confidence and unknown fields rejected",()=>{Throws(()=>DeviceAI.Parse(Reply("surveillance_target"),Inputs("iphone")));Throws(()=>DeviceAI.Parse(Reply("iphone","high"),Inputs("iphone")));Throws(()=>DeviceAI.Parse(Reply("iphone").Replace("\"Type\":","\"Extra\":1,\"Type\":"),Inputs("iphone")));});
  Test("markdown trailing prose and JavaScript extensions rejected",()=>{string json=Reply("iphone");foreach(string raw in new[]{"```json\n"+json+"\n```",json+"extra",json.Replace("\"Devices\"","Devices"),json.Replace("}]}","},]}")})Throws(()=>DeviceAI.Parse(raw,Inputs("iphone")));});
  Test("duplicate root nested and escaped keys rejected",()=>{string json=Reply("iphone");Throws(()=>DeviceAI.Parse(json.Replace("\"Devices\":","\"Devices\":[],\"Devices\":"),Inputs("iphone")));Throws(()=>DeviceAI.Parse(json.Replace("\"Type\":","\"Type\":\"unknown\",\"Type\":"),Inputs("iphone")));Throws(()=>DeviceAI.Parse(json.Replace("\"Type\":","\"\\u0054ype\":\"unknown\",\"Type\":"),Inputs("iphone")));});
  Test("missing extra and repeated aliases rejected",()=>{Throws(()=>DeviceAI.Parse("{\"Devices\":[]}",Inputs("iphone")));Throws(()=>DeviceAI.Parse(Reply("iphone").Replace("device-01","device-02"),Inputs("iphone")));string row=Reply("iphone");string item=row.Substring(row.IndexOf('[')+1,row.LastIndexOf(']')-row.IndexOf('[')-1);Throws(()=>DeviceAI.Parse("{\"Devices\":["+item+","+item+"]}",Inputs("iphone")));});
  Test("batch bounded at 32 without accepting duplicate input aliases",()=>{var input=Enumerable.Range(1,33).Select(i=>new DeviceAIInput{Alias="device-"+i.ToString("00"),Clues=new List<string>{"iphone"}}).ToList();Throws(()=>DeviceAI.InputJson(input));input.RemoveAt(32);Check(DeviceAI.InputJson(input).Length>0,"32 batch rejected");input[1].Alias=input[0].Alias;Throws(()=>DeviceAI.InputJson(input));});
  Test("schema is strict at all object levels",()=>{var schema=Store.Parse<Dictionary<string,object>>(DeviceAI.SchemaJson);Check((bool)schema["additionalProperties"]==false,"root loose");var properties=(Dictionary<string,object>)schema["properties"];var devices=(Dictionary<string,object>)properties["Devices"];Check(Convert.ToInt32(devices["maxItems"])==32,"batch not bounded");var item=(Dictionary<string,object>)devices["items"];Check((bool)item["additionalProperties"]==false,"row loose");});
  Test("valid guess never overwrites raw name or supplied type hint",()=>{var device=Device();var guess=DeviceAI.Parse(Reply("iphone"),Inputs("iphone"))["device-01"];Check(DeviceAI.Apply(device,guess),"guess not applied");Check(device.Name=="Alice-iphone"&&device.Hint=="设备类型未知"&&device.InferredType=="iphone","name or confirmed hint overwritten");});
  Test("manual and self-reported devices are not overwritten",()=>{var guess=DeviceAI.Parse(Reply("iphone"),Inputs("iphone"))["device-01"];foreach(string source in new[]{"人工确认 / 本地标签","本机 Windows 自报"}){var device=Device();device.NameSource=source;device.InferredType="stale";Check(!DeviceAI.Apply(device,guess)&&device.InferredType==null,"confirmed type overwritten");}});
  Test("stale or changed clue guesses are discarded",()=>{var guess=DeviceAI.Parse(Reply("iphone"),Inputs("iphone"))["device-01"];Check(!DeviceAI.Apply(Device("New-windows"),guess),"old identity evidence reused");guess.At=DateTime.UtcNow.AddDays(-31);Check(!DeviceAI.Apply(Device(),guess),"old guess not expired");});
  Test("MAC validation rejects malformed or zero/broadcast keys",()=>{Check(DeviceAI.MacKey("aa-bb-cc-11-22-33")=="AABBCC112233","normalization wrong");foreach(string key in new[]{"not-a-mac","00:00:00:00:00:00","FF:FF:FF:FF:FF:FF","aa:bb:cc:11:22:3z"})Check(DeviceAI.MacKey(key)==null,"invalid key accepted");});
  Test("controller no-information path calls no model and keeps unknown",()=>{using(var c=Controller(Temp())){Set(c,"devices",new List<DeviceInfo>{Device("Unknown")});c.GuessDeviceTypesAsync().GetAwaiter().GetResult();Check(c.AiCallsToday==0,"unknown spent model call");Check(c.Devices[0].InferredType=="unknown","unknown not explicit");Check(!c.IsAnalyzing,"mutex not released");}});
  Test("controller shares analysis mutex without releasing another task",()=>{using(var c=Controller(Temp())){Set(c,"analyzing",1);Throws(()=>c.GuessDeviceTypesAsync().GetAwaiter().GetResult());Check(c.IsAnalyzing,"other task mutex released");Set(c,"analyzing",0);}});
  Test("controller respects daily budget before spawning a child",()=>{using(var c=Controller(Temp())){var settings=c.Settings;settings.CodexPath=typeof(object).Assembly.Location;settings.MaxAiCallsPerDay=0;c.SaveSettings(settings);Set(c,"devices",new List<DeviceInfo>{Device()});Throws(()=>c.GuessDeviceTypesAsync().GetAwaiter().GetResult());Check(c.AiCallsToday==0&&!c.IsAnalyzing,"budget bypassed or mutex stuck");}});
  Test("saved guesses recover by MAC across restart and preserve manual labels",()=>{string dir=Temp();var guess=DeviceAI.Parse(Reply("iphone"),Inputs("iphone"))["device-01"];using(var c=Controller(dir)){File.WriteAllText(Path.Combine(dir,"device-ai-guesses.json"),Store.Json(new Dictionary<string,DeviceAIInference>{{"AABBCC112233",guess}}));}using(var c=new AppController(dir)){Set(c,"devices",new List<DeviceInfo>{Device()});Map(c);Check(c.Devices[0].InferredType=="iphone","guess not restored");c.SetDeviceLabel("AA:BB:CC:11:22:33","My computer","Windows");Check(c.Devices[0].Name=="My computer"&&c.Devices[0].InferredType==null,"manual label did not supersede guess");c.SetDeviceLabel("AA:BB:CC:11:22:33","","");Check(c.Devices[0].Name=="Alice-iphone"&&c.Devices[0].InferredType=="iphone","clearing label failed to restore independent inference");}});
  Test("resolved name source survives mapping and manual label clear",()=>{using(var c=Controller(Temp())){var d=Device("Peer-iphone");d.Source="Windows 邻居缓存；接口 1";d.ReportedNameSource=DeviceIdentity.NetworkNameSource;Set(c,"devices",new List<DeviceInfo>{d});Map(c);Check(c.Devices[0].NameSource==DeviceIdentity.NetworkNameSource,"resolved source lost");c.SetDeviceLabel(d.Mac,"Manual","");c.SetDeviceLabel(d.Mac,"","");Check(c.Devices[0].NameSource==DeviceIdentity.NetworkNameSource&&c.Devices[0].Name=="Peer-iphone","clear did not restore network-supplied name source");}});
  Test("explicit name lookup leaves imported records untouched without DNS",()=>{using(var c=Controller(Temp())){var d=Device();Set(c,"devices",new List<DeviceInfo>{d});c.ResolveDeviceNamesAsync().GetAwaiter().GetResult();Check(c.Devices.Count==1&&c.Devices[0].Name==d.Name&&c.Devices[0].Source=="网关导入快照","imported row changed");Check(c.AiCallsToday==0,"name lookup used model quota");}});  Console.WriteLine("RESULT "+passed+" passed, "+failed+" failed. Synthetic/local only; no model, network, or monitoring timer was started.");return failed==0?0:1;
 }
}

